/**
 * 单元测试用明确目标／行动组合及历史变化验证预言家的共享政策。原 schema、gateway、
 * DTO 和库存断言验证配置语义；输入及字面／不可变 fixture 预期保持原样，不运行模型
 * 或完整对局驱动。
 */
import { captureNativeRolePresentation } from "../../../../src/game/observation/native-role-presentation-capture";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import {
  COMPONENT,
  Phase,
  Role,
  type BoardConfig,
  type ActionRequest,
  type GameEvent,
  type RoleComponent,
  type ToolCall,
} from "../../../../src/core";
import { GameActionRequestFactory } from "../../../../src/game/engine/action_request_factory";
import { SEER_NIGHT_STAGES } from "../../../../src/game/mechanisms/roles/seer/night_stages";
import { SEER_ROLE_PROFILE } from "../../../../src/game/mechanisms/roles/seer/profile";
import {
  findNightAbility,
} from "../../../../src/game/mechanisms/roles/abilities";
import { projectNightAbility } from "../../../../src/game/observation/night-ability-projection";
import { getDefaultTargetHintRegistry } from "../../../../src/game/mechanisms/llm/target_hint_registry";
import { getDefaultConfigRenderRegistry } from "../../../../src/game/mechanisms/prompt/config_render_registry";
import { boardConfigSchema } from "../../../../src/core/domain/board_schema";
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
} from "../../../../src/runtime/config/board_definition";
import { sixPlayerMvpConfig } from "../../../../src/runtime/scenarios/six_player_mvp";
import { nightStageContext } from "../../../support/builders/night-stage-context";
import { ObservedBot } from "../../../../src/ai/agents/providers/observed_bot";
import { ObservedPlayersActionProvider } from "../../../../src/ai/agents/providers/observed_players";

const roles = [Role.Wolf, Role.Seer, Role.Villager, Role.Guard, Role.Villager, Role.Villager];
function setup(parameters?: BoardConfig["seer"], locale: "zh-CN" | "en" = "en") {
  const config: BoardConfig = {
    ...sixPlayerMvpConfig,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
      count: roles.filter((x) => x === role).length,
    })),
    ...(parameters ? { seer: parameters } : {}),
  };
  const resolved = parseBoardDefinition(boardDefinitionFromConfig("seer_policy", config));
  const game = bootstrapGame(resolved.config, { fixedRoles: roles, locale });
  const ability = findNightAbility(
    game.world.getComponent(2, COMPONENT.Role),
    "seer_check",
  )!;
  const events: GameEvent[] = [];
  const requests: ActionRequest[] = [];
  const act = async (day: number, target: number | null, mutate?: () => void) => {
    const factory = new GameActionRequestFactory(game.world, events, day);
    await SEER_NIGHT_STAGES[0].execute(
      nightStageContext({
        world: game.world,
        events,
        currentDay: () => day,
        makeRequest: (actorId, allowedTools, extra) =>
          factory.create({
            actorId,
            allowedTools,
            phase: Phase.Night,
            stage: extra.stage,
            context: extra,
            requiresAction: extra.requiresAction ?? false,
            summary: "Offline policy",
          }),
        actionProvider: {
          async getAction(request) {
            requests.push(request);
            mutate?.();
            return target === null ? null : { name: "check_identity", args: { target_id: target } };
          },
        },
      }),
    );
  };
  return { ...game, ...resolved, ability, events, requests, act };
}
for (const targetPolicy of ["awa_alive_v1", "awa_fresh_others_v1"] as const)
  for (const actionPolicy of ["awa_optional_v1", "awa_required_when_legal_v1"] as const)
    test(`${targetPolicy}/${actionPolicy}: real stage, gateway, normalized schema and DTO agree`, async () => {
      const game = setup({ targetPolicy, actionPolicy });
      expect(game.config.seer).toEqual({ targetPolicy, actionPolicy });
      expect(boardConfigSchema.parse(JSON.parse(JSON.stringify(game.config))).seer).toEqual(
        game.config.seer,
      );
      expect(
        parseBoardDefinition(boardDefinitionFromConfig("seer_policy", game.config)).config.seer,
      ).toEqual(game.config.seer);
      await game.act(1, 1);
      expect(game.requests[0].context.turn_constraints.min_valid_actions).toBe(
        actionPolicy === "awa_required_when_legal_v1" ? 1 : 0,
      );
      expect(game.ability.state.history).toHaveLength(1);
      await game.act(2, 1);
      expect(game.ability.state.history).toHaveLength(
        targetPolicy === "awa_fresh_others_v1" ? 1 : 2,
      );
      await game.act(3, 2);
      expect(game.ability.state.history.some((row) => row.targetId === 2)).toBe(
        targetPolicy === "awa_alive_v1",
      );
      const projected = projectNightAbility(game.ability, 4);
      if (projected.kind !== "seer_check") throw new Error("expected_seer_projection");
      expect<unknown>(projected.state.history).toEqual(game.ability.state.history);
      if (targetPolicy === "awa_fresh_others_v1")
        expect(projected.state.targetPolicy).toBe(targetPolicy);
      const hint = getDefaultTargetHintRegistry().buildActionableIdsHint({
        world: game.world,
        actorId: 2,
        actorRole: Role.Seer,
        day: 4,
        abilityId: game.ability.id,
        allowedTools: ["check_identity"],
      })!;
      const ids = hint.match(/\b\d+\b/g)?.map(Number) ?? [];
      expect(ids.includes(1)).toBe(targetPolicy === "awa_alive_v1");
    });

test("fresh target policy rechecks history after await and exhausts without an impossible forced request", async () => {
  const game = setup({
    targetPolicy: "awa_fresh_others_v1",
    actionPolicy: "awa_required_when_legal_v1",
  });
  await game.act(1, 1, () =>
    (
      game.ability.state.history as {
        targetId: import("@ai-werewolf-arena/game-contract").EntityId;
        isWerewolf: boolean;
        result?: import("@ai-werewolf-arena/game-contract").InspectionResult;
      }[]
    ).push({ targetId: 1, isWerewolf: true }),
  );
  expect(game.events.filter((event) => event.type === "seer_checked")).toHaveLength(0);
  for (const targetId of [3, 4, 5, 6])
    (
      game.ability.state.history as {
        targetId: import("@ai-werewolf-arena/game-contract").EntityId;
        isWerewolf: boolean;
        result?: import("@ai-werewolf-arena/game-contract").InspectionResult;
      }[]
    ).push({ targetId, isWerewolf: false });
  await game.act(2, 3);
  expect(game.requests).toHaveLength(1);
  expect(game.ability.lastUsedDay).toBeNull();
  const factory = new GameActionRequestFactory(game.world, game.events, 3);
  const req = factory.create({
    actorId: 2,
    allowedTools: ["check_identity"],
    phase: Phase.Night,
    stage: "seer",
    context: { ability_id: game.ability.id },
    requiresAction: false,
    summary: "Exhausted",
  });
  const role = game.world.getComponent(2, COMPONENT.Role)!;
  expect(
    SEER_ROLE_PROFILE.runtime.baselineAction!(
      role,
      req,
      () => 1,
      () => 1,
      "en",
      game.world,
    ),
  ).toBeNull();
  const provider = new ObservedPlayersActionProvider(
    game.world,
    new Map([[2, new ObservedBot({ next: () => 0 }, "active")]]),
    game.config,
  );
  await expect(provider.getAction(req)).resolves.toBeNull();
});

for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: named AWA policies are visible in role and board prompts`, () => {
    const game = setup(
      { targetPolicy: "awa_fresh_others_v1", actionPolicy: "awa_required_when_legal_v1" },
      locale,
    );
    const prompt = captureNativeRolePresentation(
      SEER_ROLE_PROFILE.presentation!.id,
      game.world.getComponent(2, COMPONENT.Role)!,
      locale,
    );
    const board = getDefaultConfigRenderRegistry().renderBoardConfigPrompt(game.config, locale);
    expect(prompt).toContain(locale === "en" ? "history never resets" : "不重置历史");
    expect(board).toContain(
      locale === "en" ? "required while a legal target" : "存在合法目标时必须",
    );
  });

test("seer policy rejects unknown versions and parameters without that role", () => {
  const game = setup();
  const raw = boardDefinitionFromConfig("seer_policy", game.config);
  expect(() =>
    parseBoardDefinition({
      ...raw,
      roles: { ...raw.roles, seer: { targetPolicy: "global_no_repeat" } },
    }),
  ).toThrow();
  expect(() =>
    parseBoardDefinition({
      ...raw,
      board: {
        ...raw.board,
        roleSetups: raw.board.roleSetups.map((row) =>
          row.role === "seer" ? { role: "villager", count: row.count } : row,
        ),
      },
      roles: { seer: { targetPolicy: "awa_fresh_others_v1" } },
    }),
  ).toThrow();
});

/**
 * 单元测试：验证配置的查验／死亡政策在有界阶段、hook、校验、提示与投影中的实际使用。输入为角色／政策／语言矩阵和原 live 槽修改；手写许可、库存／历史计数和错误为预期。死亡链在场景中，此处不运行完整阶段或模型。
 */
import { rolePresentationRenderer } from "../../../src/game/observation/role-presentation";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  COMPONENT,
  DeathCause,
  Phase,
  Role,
  permitsDeathShot,
  type BoardConfig,
  type ActionRequest,
  type GameEvent,
  type RoleComponent,
  type DeathActionPolicy,
  type InspectionPolicy,
} from "../../../src/core";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
} from "../../../src/runtime/config/board_definition";
import { boardConfigSchema } from "../../../src/core/domain/board_schema";
import { getDefaultRoleCatalog } from "../../../src/game/mechanisms/roles/role-catalog-assembly";
import {
  findNightAbility,
} from "../../../src/game/mechanisms/roles/abilities";
import { projectNightAbility } from "../../../src/game/observation/night-ability-projection";
import {
  grantNightAbility,
  transferNightAbility,
} from "../../../src/game/mechanisms/roles/ability_changes";
import {
  ROLE_INSPECTION_STAGE,
  PSYCHIC_INSPECTION_STAGE,
  MIRROR_INSPECTION_STAGE,
} from "../../../src/game/mechanisms/roles/role_inspection/night_stages";
import { roleInspectionTargets } from "../../../src/game/mechanisms/roles/role_inspection/rules";
import { getHunterState } from "../../../src/game/mechanisms/roles/hunter/ports";
import { getWolfKingState } from "../../../src/game/mechanisms/roles/wolf_king/ports";
import { hunterDeathHook } from "../../../src/game/mechanisms/roles/hunter/death_hook";
import { WOLF_KING_ROLE_PROFILE } from "../../../src/game/mechanisms/roles/wolf_king/profile";
import { GameActionRequestFactory } from "../../../src/game/engine/action_request_factory";
import { getDefaultTargetHintRegistry } from "../../../src/game/mechanisms/llm/target_hint_registry";
import { getDefaultConfigRenderRegistry } from "../../../src/game/mechanisms/prompt/config_render_registry";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";
import { ObservedBot } from "../../../src/ai/agents/providers/observed_bot";
import { ObservedPlayersActionProvider } from "../../../src/ai/agents/providers/observed_players";
import { nightStageContext } from "../../support/builders/night-stage-context";

const inspectionPolicies = [
  "awa_unique_required_v1",
  "awa_repeat_optional_v1",
  "awa_unique_optional_v1",
] as const;

const deathPolicies = ["awa_qualified_sources_v1", "awa_knife_or_exile_v1"] as const;

const keys = {
  [Role.Gargoyle]: "gargoyle",
  [Role.Psychic]: "psychic",
  [Role.MirrorGirl]: "mirrorGirl",
  [Role.Hunter]: "hunter",
  [Role.WolfKing]: "wolfKing",
} as const;

function fixture(
  kind: keyof typeof keys,
  parameters?: { inspectionPolicy: InspectionPolicy } | { deathActionPolicy: DeathActionPolicy },
  locale: "zh-CN" | "en" = "en",
) {
  const roles = [kind, Role.Wolf, Role.Seer, Role.Witch, Role.Villager, Role.Villager];
  const raw: BoardConfig = {
    ...sixPlayerMvpConfig,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
      count: roles.filter((x) => x === role).length,
    })),
    ...(parameters ? { [keys[kind]]: parameters } : {}),
  };
  const config = parseBoardDefinition(boardDefinitionFromConfig("role_policy", raw)).config;
  return { ...bootstrapGame(config, { fixedRoles: roles, locale }), config };
}

for (const kind of [
  Role.Gargoyle,
  Role.Psychic,
  Role.MirrorGirl,
  Role.Hunter,
  Role.WolfKing,
] as const)
  test(`${kind}: omitted, empty, explicit defaults and legacy reverse config normalize identically; unknown variants fail closed`, () => {
    const game = fixture(kind),
      contribution = getDefaultRoleCatalog().requireRuntime(kind).configuration!;
    const publicBoard = boardDefinitionFromConfig("role_policy", game.config);
    const omitted = structuredClone(publicBoard);
    delete omitted.roles[kind];
    const empty = structuredClone(publicBoard);
    empty.roles[kind] = {};
    expect(contribution.schema.parse({})).toEqual(contribution.defaults);
    expect(parseBoardDefinition(omitted).config).toEqual(game.config);
    expect(parseBoardDefinition(empty).config).toEqual(game.config);
    expect(boardConfigSchema.parse(JSON.parse(JSON.stringify(game.config)))).toEqual(game.config);
    expect(() =>
      parseBoardDefinition({
        ...publicBoard,
        roles: { ...publicBoard.roles, [kind]: { unknown: true } },
      }),
    ).toThrow();
    const field =
      kind === Role.Hunter || kind === Role.WolfKing ? "deathActionPolicy" : "inspectionPolicy";
    expect(() =>
      parseBoardDefinition({
        ...publicBoard,
        roles: { ...publicBoard.roles, [kind]: { [field]: "universal" } },
      }),
    ).toThrow();
  });

for (const kind of [Role.Gargoyle, Role.Psychic, Role.MirrorGirl] as const)
  for (const policy of inspectionPolicies)
    for (const locale of ["zh-CN", "en"] as const)
      test(`${kind}/${policy}/${locale}: real stage, late validation, target hints, baseline and DTO consume instance policy without changing identity`, async () => {
        const game = fixture(kind, { inspectionPolicy: policy }, locale),
          role = game.world.getComponent(1, COMPONENT.Role)!;
        const ability = findNightAbility(role, "role_check")!;
        const stage =
          kind === Role.Gargoyle
            ? ROLE_INSPECTION_STAGE
            : kind === Role.Psychic
              ? PSYCHIC_INSPECTION_STAGE
              : MIRROR_INSPECTION_STAGE;
        const requests: ActionRequest[] = [],
          events: GameEvent[] = [];
        const act = async (day: number, target: number | null) => {
          const factory = new GameActionRequestFactory(game.world, events, day);
          await stage.execute(
            nightStageContext({
              world: game.world,
              events,
              currentDay: () => day,
              makeRequest: (actorId, allowedTools, extra) =>
                factory.create({
                  actorId,
                  allowedTools,
                  phase: Phase.Night,
                  stage: extra.stage,
                  context: extra,
                  requiresAction: extra.requiresAction ?? true,
                  summary: "Offline",
                }),
              actionProvider: {
                async getAction(request) {
                  requests.push(request);
                  return target === null
                    ? null
                    : { name: "inspect_role", args: { target_id: target } };
                },
              },
            }),
          );
        };
        await act(1, 2);
        expect(requests[0].context.stage).toBe(
          kind === Role.Gargoyle
            ? "role_inspection"
            : kind === Role.Psychic
              ? "psychic"
              : "mirror_girl",
        );
        expect(requests[0].context.turn_constraints.min_valid_actions).toBe(
          policy === "awa_unique_required_v1" ? 1 : 0,
        );
        expect(ability.state.history).toHaveLength(1);
        const repeated = roleInspectionTargets(game.world, 1, ability.state).includes(2);
        expect(repeated).toBe(policy === "awa_repeat_optional_v1");
        const gateway = new ToolGateway();
        expect(
          gateway.validateAndSanitize(
            game.world,
            1,
            { name: "inspect_role", args: { target_id: 2 } },
            { phase: Phase.Night, day: 2, abilityId: ability.id },
          ).ok,
        ).toBe(repeated);
        const hint = getDefaultTargetHintRegistry().buildActionableIdsHint({
          world: game.world,
          actorId: 1,
          actorRole: kind,
          day: 2,
          abilityId: ability.id,
          allowedTools: ["inspect_role"],
        })!;
        expect(
          hint
            .match(/\b\d+\b/g)
            ?.map(Number)
            .includes(2),
        ).toBe(repeated);
        const factory = new GameActionRequestFactory(game.world, events, 2);
        const request = factory.create({
          actorId: 1,
          allowedTools: ["inspect_role"],
          phase: Phase.Night,
          stage: requests[0].context.stage,
          context: { ability_id: ability.id },
          requiresAction: policy === "awa_unique_required_v1",
          summary: "Offline",
        });
        const baseline = getDefaultRoleCatalog().requireRuntime(kind).baselineAction!(
          role,
          request,
          () => 2,
          () => 2,
          locale,
          game.world,
        );
        expect(baseline?.name).toBe("inspect_role");
        if (baseline?.name === "inspect_role")
          expect(roleInspectionTargets(game.world, 1, ability.state)).toContain(
            baseline.args.target_id,
          );
        const observed = new ObservedPlayersActionProvider(
          game.world,
          new Map([[1, new ObservedBot({ next: () => 0 }, "conservative")]]),
          game.config,
        );
        const bot = await observed.getAction(request);
        expect(bot === null).toBe(policy !== "awa_unique_required_v1");
        if (policy !== "awa_unique_required_v1") {
          await act(2, null);
          expect(ability.lastUsedDay).toBe(2);
          expect(ability.uses).toBe(1);
        }
        const dto = projectNightAbility(ability, 3);
        expect(dto.kind).toBe("role_check");
        if (dto.kind === "role_check")
          expect<unknown>(dto.state.history).toEqual(ability.state.history);
        expect(
          getDefaultConfigRenderRegistry().renderBoardConfigPrompt(game.config, locale),
        ).toContain(locale === "en" ? "Configured AWA inspection" : "配置的AWA查验");
        expect(rolePresentationRenderer(role)?.(locale)).toContain(
          locale === "en" ? "Configured AWA inspection" : "配置的AWA查验",
        );
        expect(role.role).toBe(kind);
      });

for (const kind of [Role.Gargoyle, Role.Psychic, Role.MirrorGirl] as const)
  for (const point of ["construct", "await", "gateway"] as const)
    test(`${kind}/${point}: policy mutation revokes pending inspection rather than reinterpreting it`, async () => {
      const game = fixture(kind, { inspectionPolicy: "awa_unique_required_v1" }),
        role = game.world.getComponent(1, COMPONENT.Role)!,
        ability = findNightAbility(role, "role_check")!,
        events: GameEvent[] = [];
      const stage =
        kind === Role.Gargoyle
          ? ROLE_INSPECTION_STAGE
          : kind === Role.Psychic
            ? PSYCHIC_INSPECTION_STAGE
            : MIRROR_INSPECTION_STAGE;
      const factory = new GameActionRequestFactory(game.world, events, 1),
        gateway = new ToolGateway();
      let asks = 0;
      const mutate = () => {
        (
          ability.state as {
            inspectionPolicy:
              | "awa_unique_required_v1"
              | "awa_repeat_optional_v1"
              | "awa_unique_optional_v1"
              | undefined;
          }
        ).inspectionPolicy = "awa_repeat_optional_v1";
      };
      if (point === "gateway") {
        const original = gateway.validateAndSanitize.bind(gateway);
        gateway.validateAndSanitize = (...args) => {
          const result = original(...args);
          mutate();
          return result;
        };
      }
      await stage.execute(
        nightStageContext({
          world: game.world,
          events,
          toolGateway: gateway,
          makeRequest: (actorId, allowedTools, extra) => {
            const request = factory.create({
              actorId,
              allowedTools,
              phase: Phase.Night,
              stage: extra.stage,
              context: extra,
              requiresAction: extra.requiresAction ?? true,
              summary: "Offline",
            });
            if (point === "construct") mutate();
            return request;
          },
          actionProvider: {
            async getAction() {
              asks++;
              if (point === "await") mutate();
              return { name: "inspect_role", args: { target_id: 2 } };
            },
          },
        }),
      );
      expect(asks).toBe(point === "construct" ? 0 : 1);
      expect(ability.state.history).toEqual([]);
      expect(ability.uses).toBe(0);
      expect(ability.lastUsedDay).toBeNull();
      expect(events.filter((e) => e.type === "role_inspected")).toEqual([]);
    });

for (const kind of [Role.Hunter, Role.WolfKing] as const)
  for (const policy of deathPolicies)
    test(`${kind}/${policy}: every single and compound death cause follows native policy; poison, empty and unknown remain blocked`, async () => {
      const eligible = [
        DeathCause.WolfKill,
        DeathCause.MechanicalKnife,
        DeathCause.AwakenedHiddenKnife,
        DeathCause.Exile,
        ...(policy === "awa_qualified_sources_v1"
          ? [DeathCause.Shot, DeathCause.WhiteWolfBlast]
          : []),
      ];
      const cases = [
        ...Object.values(DeathCause).map((c) => [c]),
        [],
        [DeathCause.WolfKill, DeathCause.Exile],
        [DeathCause.WolfKill, DeathCause.Shot],
        [DeathCause.WolfKill, DeathCause.Poison],
        [DeathCause.Shot, DeathCause.Charm],
        ["unknown" as DeathCause],
      ];
      for (const sources of cases) {
        const game = fixture(kind, { deathActionPolicy: policy }),
          role = game.world.getComponent(1, COMPONENT.Role)!;
        game.world.getComponent(1, COMPONENT.Alive)!.alive = false;
        let asks = 0;
        const events: GameEvent[] = [];
        const hook =
          kind === Role.Hunter ? hunterDeathHook : WOLF_KING_ROLE_PROFILE.runtime.deathHook!;
        let permit: ReturnType<typeof game.world.openDeathAction> | undefined;
        const result = await hook(
          game.world,
          [1],
          { 1: sources },
          async () => {
            asks++;
            permit = game.world.openDeathAction(1, "shoot", Phase.Day, 1);
            return { kind: "shot", targetId: 2, deathActionId: permit.id };
          },
          events,
        );
        permit?.close();
        const can = sources.length > 0 && sources.every((c) => eligible.includes(c));
        expect(permitsDeathShot(sources, policy)).toBe(can);
        expect(asks).toBe(can ? 1 : 0);
        expect(result.extraDeaths).toEqual(can ? [2] : []);
        expect(
          kind === Role.Hunter ? getHunterState(role)?.canShoot : getWolfKingState(role)?.canShoot,
        ).toBe(false);
      }
    });

test("gift/copy explicit inspection state is independent of holder board; transfer retains configured history", () => {
  const game = fixture(Role.Psychic, { inspectionPolicy: "awa_unique_required_v1" }),
    events: GameEvent[] = [];
  const gift = grantNightAbility(
    game.world,
    5,
    {
      id: "gift:policy",
      kind: "role_check",
      state: {
        policy: "psychic",
        inspectionPolicy: "awa_repeat_optional_v1",
        lastTarget: null,
        lastDay: null,
        history: [],
      },
      source: { kind: "gift", actorId: 1 },
      startsOnDay: 1,
      maxUses: null,
    },
    events,
  );
  (
    gift.state.history as {
      day: number;
      targetId: import("@ai-werewolf-arena/game-contract").EntityId;
      result: Extract<
        import("@ai-werewolf-arena/game-contract").InspectionResult,
        { kind: "role" }
      >;
    }[]
  ).push({ day: 1, targetId: 2, result: { kind: "role", role: Role.Wolf } });
  expect(roleInspectionTargets(game.world, 5, gift.state)).toContain(2);
  transferNightAbility(game.world, 5, 6, gift.id, "transfer:policy", events, {
    kind: "role_check",
    statePolicy: (state) => structuredClone(state),
  });
  const transferred = findNightAbility(
    game.world.getComponent(6, COMPONENT.Role),
    "role_check",
    "transfer:policy",
  )!;
